PACKAGE pkg_simple_oma AS
    PROCEDURE add_bonus (p_user_id IN NUMBER, p_bonus IN NUMBER);
    FUNCTION get_user_total (p_user_id IN NUMBER) RETURN NUMBER;
END pkg_simple_oma;

PACKAGE BODY pkg_simple_oma AS
    PROCEDURE add_bonus (p_user_id IN NUMBER, p_bonus IN NUMBER) IS
    BEGIN
        UPDATE oma_test_users
           SET balance = balance + p_bonus
         WHERE user_id = p_user_id;
        COMMIT;
    END add_bonus;

    FUNCTION get_user_total (p_user_id IN NUMBER) RETURN NUMBER IS
        l_total NUMBER := 0;
    BEGIN
        SELECT NVL(SUM(amount), 0)
          INTO l_total
          FROM oma_test_orders
         WHERE user_id = p_user_id;
        RETURN l_total;
    END get_user_total;
END pkg_simple_oma;

PROCEDURE sp_load_accounts_with_errlog IS
BEGIN
    INSERT INTO oma_target_accounts (account_id, account_name, balance)
    SELECT account_id, account_name, balance
    FROM oma_stage_accounts
    LOG ERRORS INTO err$_oma_target_accounts ('OMA_LOAD_BATCH_01')
    REJECT LIMIT UNLIMITED;

    DBMS_OUTPUT.PUT_LINE('Valid rows inserted into target: ' || SQL%ROWCOUNT);
    COMMIT;
END sp_load_accounts_with_errlog;

PROCEDURE sp_simple_load (
    p_loops IN NUMBER DEFAULT 50
) IS
    l_cnt NUMBER;
BEGIN
    FOR i IN 1 .. p_loops LOOP
        SELECT COUNT(*) INTO l_cnt FROM oma_test_orders WHERE user_id = 1;

        INSERT INTO oma_test_orders (order_id, user_id, amount, status)
        VALUES (1000 + i, MOD(i, 3) + 1, i * 10, 'COMPLETED');

        UPDATE oma_test_users
           SET balance = balance + 10
         WHERE user_id = MOD(i, 3) + 1;
    END LOOP;
    COMMIT;
END sp_simple_load;
